//! UART driver
//!
//! Blocking UART drivers for USART1 (APB2) and USART2/USART3/UART4 (APB1),
//! with DMA transfer helpers and interrupt support. Each instance is
//! generated by the [`impl_uart!`] macro from the PAC peripherals, following
//! the rp2350 `UartBus` style.
//!
//! # Example
//!
//! ```ignore
//! use ch32x035::{Rcc, Clocks, uart::{Uart1, Config}};
//!
//! let mut rcc = Rcc::new(dp.RCC);
//! let clocks = Clocks::new(&rcc);
//! let mut uart = Uart1::init(dp.USART1, &mut rcc, clocks, Config::default());
//! uart.write_str("Hello!\r\n");
//! ```

use core::fmt;

use crate::Steal;
use crate::dma::{DataSize, DmaChannel, DmaDir};
use crate::pac;
use crate::rcc::{Clocks, Rcc};
use crate::reset::Resettable;

/// Word length (data bits)
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DataBits {
    /// 8 data bits
    Eight,
    /// 9 data bits
    Nine,
}

/// Parity setting
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Parity {
    /// No parity
    None,
    /// Even parity
    Even,
    /// Odd parity
    Odd,
}

/// Stop bits
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StopBits {
    /// 1 stop bit
    Stop1,
    /// 2 stop bits
    Stop2,
}

/// Hardware flow control (RS232 RTS/CTS).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FlowControl {
    /// No flow control.
    None,
    /// RTS output (receiver-ready signal).
    Rts,
    /// CTS input (clear-to-send signal).
    Cts,
    /// Both RTS output and CTS input.
    RtsCts,
}

/// UART configuration
#[derive(Clone, Copy, Debug)]
pub struct Config {
    /// Baud rate (bits per second)
    pub baudrate: u32,
    /// Data bits
    pub data_bits: DataBits,
    /// Parity
    pub parity: Parity,
    /// Stop bits
    pub stop_bits: StopBits,
    /// Hardware flow control (RTS/CTS).
    pub flow_control: FlowControl,
    /// Single-wire half-duplex mode.
    pub half_duplex: bool,
    /// IrDA (infrared) mode.
    pub irda: bool,
    /// LIN mode (11-bit break detection).
    pub lin: bool,
    /// Enable the RX DMA request.
    pub dma_rx: bool,
    /// Enable the TX DMA request.
    pub dma_tx: bool,
}

impl Default for Config {
    fn default() -> Self {
        Self {
            baudrate: 115_200,
            data_bits: DataBits::Eight,
            parity: Parity::None,
            stop_bits: StopBits::Stop1,
            flow_control: FlowControl::None,
            half_duplex: false,
            irda: false,
            lin: false,
            dma_rx: false,
            dma_tx: false,
        }
    }
}

/// Compute the WCH USART BRR value from the peripheral clock and baud rate.
///
/// Uses the same formula as the WCH SDK (`USART_Init`): the BRR register
/// holds `round(PCLK / baudrate)` split into a 12-bit mantissa and a 4-bit
/// fraction.
fn compute_brr(pclk: u32, baudrate: u32) -> u16 {
    debug_assert!(baudrate != 0);
    let integerdivider = (25u64 * pclk as u64) / (4 * baudrate as u64);
    let mantissa = ((integerdivider / 100) << 4) as u16;
    let frac = integerdivider - 100 * (integerdivider / 100);
    let frac = (((frac * 16) + 50) / 100) as u16;
    if frac > 0xf {
        mantissa + (1 << 4)
    } else {
        mantissa | (frac & 0xf)
    }
}

/// USART error flags (read from STATR).
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Errors {
    /// Overrun error: a received byte was dropped.
    pub overrun: bool,
    /// Noise error.
    pub noise: bool,
    /// Framing error.
    pub framing: bool,
    /// Parity error.
    pub parity: bool,
}

impl Errors {
    /// Whether no error flag is set.
    #[inline]
    pub const fn is_empty(self) -> bool {
        !self.overrun && !self.noise && !self.framing && !self.parity
    }
}

/// UART error types (recoverable operation errors).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
#[cfg_attr(feature = "defmt", derive(defmt::Format))]
pub enum Error {
    /// Timed out waiting for data / TX FIFO space.
    Timeout,
}

/// Abstract UART bus trait for driver implementations.
///
/// This keeps drivers decoupled from concrete UART types.
pub trait UartBus {
    /// Error type returned by the bus.
    type Error;

    /// Write bytes to the UART.
    fn write(&mut self, data: &[u8]) -> Result<(), Self::Error>;

    /// Read bytes, blocking until the buffer is full.
    fn read(&mut self, buffer: &mut [u8]) -> Result<(), Self::Error>;

    /// Block until all pending transfers are complete.
    fn flush(&mut self) -> Result<(), Self::Error>;
}

/// Generate a UART driver type for a PAC USART peripheral.
macro_rules! impl_uart {
    ($name:ident, $periph:ty, $base:expr, $pclk:expr) => {
        /// Blocking UART driver
        pub struct $name {
            uart: $periph,
            clocks: Clocks,
        }

        impl $name {
            /// Create a new UART driver, resetting and clock-enabling the
            /// peripheral and applying `config`.
            pub fn init(uart: $periph, rcc: &mut Rcc, clocks: Clocks, config: Config) -> Self {
                // Reset + enable the peripheral clock
                uart.init(rcc);

                let u = Self { uart, clocks };

                // Disable the USART while configuring
                u.uart.ctlr1.clr_ue();

                // Data bits (M) + parity (PCE, PS)
                match config.data_bits {
                    DataBits::Eight => u.uart.ctlr1.clr_m(),
                    DataBits::Nine => u.uart.ctlr1.set_m(),
                }
                let (pce, ps) = match config.parity {
                    Parity::None => (0, 0),
                    Parity::Even => (1, 0),
                    Parity::Odd => (1, 1),
                };
                u.uart.ctlr1.modify_bits(|v| {
                    (v & !(pac::usart1::Ctlr1::PCE_MASK | pac::usart1::Ctlr1::PS_MASK))
                        | (pce << pac::usart1::Ctlr1::PCE_OFFSET)
                        | (ps << pac::usart1::Ctlr1::PS_OFFSET)
                });

                // Stop bits (STOP, bits 13:12 of CTLR2)
                let stop = match config.stop_bits {
                    StopBits::Stop1 => 0b00,
                    StopBits::Stop2 => 0b10,
                };
                u.uart.ctlr2.write_stop(stop);

                // Baud rate
                let pclk = $pclk(&u.clocks);
                let brr = compute_brr(pclk, config.baudrate);
                u.uart.brr.write_bits(brr as u32);

                // Hardware flow control (CTLR3: RTSE / CTSE)
                match config.flow_control {
                    FlowControl::None => {
                        u.uart.ctlr3.clr_rtse();
                        u.uart.ctlr3.clr_ctse();
                    }
                    FlowControl::Rts => {
                        u.uart.ctlr3.set_rtse();
                        u.uart.ctlr3.clr_ctse();
                    }
                    FlowControl::Cts => {
                        u.uart.ctlr3.clr_rtse();
                        u.uart.ctlr3.set_ctse();
                    }
                    FlowControl::RtsCts => {
                        u.uart.ctlr3.set_rtse();
                        u.uart.ctlr3.set_ctse();
                    }
                }

                // Single-wire half-duplex (CTLR3: HDSEL)
                if config.half_duplex {
                    u.uart.ctlr3.set_hdsel();
                } else {
                    u.uart.ctlr3.clr_hdsel();
                }

                // IrDA (CTLR3: IREN)
                if config.irda {
                    u.uart.ctlr3.set_iren();
                } else {
                    u.uart.ctlr3.clr_iren();
                }

                // LIN mode (CTLR2: LINEN)
                if config.lin {
                    u.uart.ctlr2.set_linen();
                } else {
                    u.uart.ctlr2.clr_linen();
                }

                // DMA requests (CTLR3: DMAR / DMAT)
                if config.dma_rx {
                    u.uart.ctlr3.set_dmar();
                } else {
                    u.uart.ctlr3.clr_dmar();
                }
                if config.dma_tx {
                    u.uart.ctlr3.set_dmat();
                } else {
                    u.uart.ctlr3.clr_dmat();
                }

                // Enable transmitter, receiver and the USART
                u.uart.ctlr1.set_te();
                u.uart.ctlr1.set_re();
                u.uart.ctlr1.set_ue();

                u
            }

            /// Obtain a handle without ownership checks.
            ///
            /// # Safety
            ///
            /// The caller must ensure the peripheral has been initialized and
            /// that no data races occur.
            #[inline]
            pub unsafe fn steal() -> Steal<Self> {
                Steal(Self {
                    uart: unsafe { <$periph>::steal() },
                    clocks: unsafe { Clocks::steal() },
                })
            }

            /// Write a single byte, blocking until the TX buffer is empty.
            pub fn write_byte(&mut self, byte: u8) {
                self.try_write_byte(byte)
                    .unwrap_or_else(|_| panic!("UART TX timed out"));
            }

            /// Write a single byte, returning [`Error::Timeout`] if the TX
            /// buffer never empties.
            pub fn try_write_byte(&mut self, byte: u8) -> Result<(), Error> {
                if !crate::spin::try_spin_wait(|| self.uart.statr.txe()) {
                    return Err(Error::Timeout);
                }
                self.uart.datar.write_dr(byte as u32);
                Ok(())
            }

            /// Write a byte string.
            pub fn write_str(&mut self, s: &str) {
                for b in s.bytes() {
                    self.write_byte(b);
                }
            }

            /// Write a byte slice, blocking until every byte is sent.
            pub fn write(&mut self, data: &[u8]) {
                for &b in data {
                    self.write_byte(b);
                }
            }

            /// Read a byte, blocking until data is available.
            pub fn read_byte(&mut self) -> u8 {
                self.try_read_byte()
                    .unwrap_or_else(|_| panic!("UART RX timed out"))
            }

            /// Read a byte, returning [`Error::Timeout`] if no data arrives.
            pub fn try_read_byte(&mut self) -> Result<u8, Error> {
                if !crate::spin::try_spin_wait(|| self.uart.statr.rxne()) {
                    return Err(Error::Timeout);
                }
                Ok(self.uart.datar.dr() as u8)
            }

            /// Non-blocking read: returns `Some(byte)` if data is available.
            #[inline]
            pub fn read_available(&mut self) -> Option<u8> {
                if self.uart.statr.rxne() {
                    Some(self.uart.datar.dr() as u8)
                } else {
                    None
                }
            }

            /// Read into `buf`, blocking until `buf.len()` bytes arrive.
            ///
            /// Error flags are not checked here; inspect them with
            /// [`errors`](Self::errors) / [`clear_errors`](Self::clear_errors)
            /// if you need error handling.
            pub fn read(&mut self, buf: &mut [u8]) {
                for slot in buf {
                    *slot = self.read_byte();
                }
            }

            /// Read the currently-set error flags.
            #[inline]
            pub fn errors(&self) -> Errors {
                Errors {
                    overrun: self.uart.statr.ore(),
                    noise: self.uart.statr.ne(),
                    framing: self.uart.statr.fe(),
                    parity: self.uart.statr.pe(),
                }
            }

            /// Clear the error flags.
            ///
            /// The error flags are cleared by reading STATR followed by
            /// reading DATAR (WCH/STM32 convention).
            #[inline]
            pub fn clear_errors(&mut self) {
                let _ = self.uart.statr.read_bits();
                let _ = self.uart.datar.dr();
            }

            /// Clear the idle-line (IDLE) flag.
            ///
            /// IDLE is cleared by reading STATR followed by reading DATAR,
            /// exactly like the error flags.
            #[inline]
            pub fn clear_idle(&mut self) {
                let _ = self.uart.statr.read_bits();
                let _ = self.uart.datar.dr();
            }

            /// Transmit `data` using DMA.
            ///
            /// Enables the TX DMA request, starts a memory-to-peripheral
            /// transfer into the data register, then waits for the DMA and
            /// the USART to finish shifting out the last byte.
            pub fn write_dma<const CH: u8>(
                &mut self,
                ch: &DmaChannel<CH>,
                data: &[u8],
            ) -> Result<(), Error> {
                self.set_dma_tx(true);
                ch.start(
                    DmaDir::MemoryToPeripheral,
                    $base + 0x04, // DATAR
                    data.as_ptr() as u32,
                    data.len() as u16,
                    DataSize::Byte,
                    DataSize::Byte,
                    false,
                    true,
                );
                ch.try_wait().map_err(|_| Error::Timeout)?;
                self.try_flush()
            }

            /// Receive into `data` using DMA.
            ///
            /// Enables the RX DMA request, starts a peripheral-to-memory
            /// transfer from the data register, and waits for completion.
            pub fn read_dma<const CH: u8>(
                &mut self,
                ch: &DmaChannel<CH>,
                data: &mut [u8],
            ) -> Result<(), Error> {
                self.set_dma_rx(true);
                ch.start(
                    DmaDir::PeripheralToMemory,
                    $base + 0x04, // DATAR
                    data.as_ptr() as u32,
                    data.len() as u16,
                    DataSize::Byte,
                    DataSize::Byte,
                    false,
                    true,
                );
                ch.try_wait().map_err(|_| Error::Timeout)
            }

            /// Write a 9-bit word (for [`DataBits::Nine`]).
            ///
            /// Only the low 9 bits are transmitted; in 8-bit mode the upper
            /// bits are ignored.
            pub fn write_word(&mut self, word: u16) {
                crate::spin::spin_wait("UART TX empty", || self.uart.statr.txe());
                self.uart.datar.write_dr(word as u32);
            }

            /// Start sending a break condition (TX line forced low).
            ///
            /// Keep it asserted for at least one frame duration, then call
            /// [`clear_break`](Self::clear_break).
            #[inline(always)]
            pub fn set_break(&mut self) {
                self.uart.ctlr1.set_sbk();
            }

            /// Stop the break condition started by
            /// [`set_break`](Self::set_break).
            #[inline(always)]
            pub fn clear_break(&mut self) {
                self.uart.ctlr1.clr_sbk();
            }

            /// Whether a break condition was detected on the RX line.
            #[inline(always)]
            pub fn break_detected(&self) -> bool {
                self.uart.statr.lbd()
            }

            /// Whether the RX line has been idle for a full frame.
            #[inline(always)]
            pub fn rx_idle(&self) -> bool {
                self.uart.statr.idle()
            }

            /// Whether a received byte is ready to be read (RXNE).
            ///
            /// Useful from an interrupt handler.
            #[inline(always)]
            pub fn rx_ready(&self) -> bool {
                self.uart.statr.rxne()
            }

            /// Whether the TX data register is empty and ready for the next
            /// byte (TXE). Useful from an interrupt handler.
            #[inline(always)]
            pub fn tx_ready(&self) -> bool {
                self.uart.statr.txe()
            }

            /// Enable the receive (RXNE) interrupt.
            #[inline(always)]
            pub fn enable_rx_interrupt(&mut self) {
                self.uart.ctlr1.set_rxneie();
            }

            /// Enable the transmit (TXE) interrupt.
            #[inline(always)]
            pub fn enable_tx_interrupt(&mut self) {
                self.uart.ctlr1.set_txeie();
            }

            /// Enable the transmission-complete (TC) interrupt.
            #[inline(always)]
            pub fn enable_tx_complete_interrupt(&mut self) {
                self.uart.ctlr1.set_tcie();
            }

            /// Enable the idle-line (IDLE) interrupt.
            #[inline(always)]
            pub fn enable_idle_interrupt(&mut self) {
                self.uart.ctlr1.set_idleie();
            }

            /// Enable the parity-error (PE) interrupt.
            #[inline(always)]
            pub fn enable_parity_error_interrupt(&mut self) {
                self.uart.ctlr1.set_peie();
            }

            /// Disable all USART interrupt sources.
            #[inline]
            pub fn disable_interrupts(&mut self) {
                self.uart.ctlr1.clr_rxneie();
                self.uart.ctlr1.clr_txeie();
                self.uart.ctlr1.clr_tcie();
                self.uart.ctlr1.clr_idleie();
                self.uart.ctlr1.clr_peie();
            }

            /// Enable or disable the RX DMA request (CTLR3 DMAR).
            #[inline]
            pub fn set_dma_rx(&mut self, enabled: bool) {
                if enabled {
                    self.uart.ctlr3.set_dmar();
                } else {
                    self.uart.ctlr3.clr_dmar();
                }
            }

            /// Enable or disable the TX DMA request (CTLR3 DMAT).
            #[inline]
            pub fn set_dma_tx(&mut self, enabled: bool) {
                if enabled {
                    self.uart.ctlr3.set_dmat();
                } else {
                    self.uart.ctlr3.clr_dmat();
                }
            }

            /// Set the IrDA prescaler (GPR PSC field).
            #[inline(always)]
            pub fn set_prescaler(&mut self, psc: u8) {
                self.uart.gpr.write_psc(psc as u32);
            }

            /// Set the IrDA guard time (GPR GT field).
            #[inline(always)]
            pub fn set_guard_time(&mut self, gt: u8) {
                self.uart.gpr.write_gt(gt as u32);
            }

            /// Wait until the transmission is complete (TXE + TC).
            pub fn flush(&mut self) {
                self.try_flush()
                    .unwrap_or_else(|_| panic!("UART flush timed out"));
            }

            /// Wait until the transmission is complete, returning
            /// [`Error::Timeout`] if it never completes.
            pub fn try_flush(&mut self) -> Result<(), Error> {
                if !crate::spin::try_spin_wait(|| self.uart.statr.txe()) {
                    return Err(Error::Timeout);
                }
                if !crate::spin::try_spin_wait(|| self.uart.statr.tc()) {
                    return Err(Error::Timeout);
                }
                Ok(())
            }

            /// Consume the driver and return the underlying peripheral.
            #[inline(always)]
            pub fn release(self) -> $periph {
                self.uart
            }

            /// Borrow the raw USART register block.
            #[inline(always)]
            pub fn regs(&self) -> &<$periph as core::ops::Deref>::Target {
                &self.uart
            }
        }

        impl fmt::Write for $name {
            fn write_str(&mut self, s: &str) -> fmt::Result {
                self.write_str(s);
                Ok(())
            }
        }

        impl UartBus for $name {
            type Error = Error;

            fn write(&mut self, data: &[u8]) -> Result<(), Error> {
                for &b in data {
                    self.try_write_byte(b)?;
                }
                Ok(())
            }

            fn read(&mut self, buffer: &mut [u8]) -> Result<(), Error> {
                for slot in buffer.iter_mut() {
                    *slot = self.try_read_byte()?;
                }
                Ok(())
            }

            fn flush(&mut self) -> Result<(), Error> {
                self.try_flush()
            }
        }
    };
}

impl_uart!(Uart1, pac::USART1, pac::usart1::BASE, |clocks: &Clocks| {
    clocks.apb2_hz()
});
impl_uart!(Uart2, pac::USART2, pac::usart2::BASE, |clocks: &Clocks| {
    clocks.apb1_hz()
});
impl_uart!(Uart3, pac::USART3, pac::usart3::BASE, |clocks: &Clocks| {
    clocks.apb1_hz()
});
impl_uart!(Uart4, pac::UART4, pac::uart4::BASE, |clocks: &Clocks| {
    clocks.apb1_hz()
});
